class TrieNode {
  constructor() {
    this.children = new Map(); // char -> TrieNode
    this.isEnd    = false;
  }
}

class Trie {
  constructor() { this.root = new TrieNode(); }

  // O(k) — k = word length
  insert(word) {
    let node = this.root;
    for (const ch of word) {
      if (!node.children.has(ch)) node.children.set(ch, new TrieNode());
      node = node.children.get(ch);
    }
    node.isEnd = true;
  }

  // O(k) — returns true only if exact word exists
  search(word) {
    const node = this.#walk(word);
    return node !== null && node.isEnd;
  }

  // O(k) — returns true if any stored word starts with prefix
  startsWith(prefix) {
    return this.#walk(prefix) !== null;
  }

  // O(p + n) — all words with given prefix
  autocomplete(prefix) {
    const node = this.#walk(prefix);
    if (!node) return [];
    const results = [];
    this.#dfs(node, prefix, results);
    return results;
  }

  #walk(str) {
    let node = this.root;
    for (const ch of str) {
      if (!node.children.has(ch)) return null;
      node = node.children.get(ch);
    }
    return node;
  }

  #dfs(node, current, results) {
    if (node.isEnd) results.push(current);
    for (const [ch, child] of node.children)
      this.#dfs(child, current + ch, results);
  }
}

const trie = new Trie();
['cat','car','card','care','dog','door'].forEach(w => trie.insert(w));

console.log(trie.search('car'));          // true
console.log(trie.search('ca'));           // false (not end-of-word)
console.log(trie.startsWith('ca'));       // true
console.log(trie.autocomplete('ca'));     // ['cat','car','card','care']
console.log(trie.autocomplete('do'));     // ['dog','door']
console.log(trie.autocomplete('xyz'));    // []

// Trie vs HashMap for prefix problems
//
// HashMap: O(k) insert/search, but NO prefix enumeration without full scan
// Trie:    O(k) insert/search, O(p+n) prefix enumeration

// Space comparison for 1 000 words avg length 6:
// - Naive array-child trie: 1000 nodes × 26 slots = 26 000 refs
// - Map-child trie: ~1000 nodes × avg_children ≈ much less
// - Compressed trie (radix): fewer nodes, edge labels are substrings

// Delete a word from trie (post-order cleanup)
function deleteWord(root, word, depth = 0) {
  if (!root) return false;
  if (depth === word.length) {
    if (!root.isEnd) return false; // word never existed
    root.isEnd = false;
    return root.children.size === 0; // safe to delete if leaf
  }
  const ch   = word[depth];
  const child = root.children.get(ch);
  if (!child) return false;
  const shouldDelete = deleteWord(child, word, depth + 1);
  if (shouldDelete) {
    root.children.delete(ch);
    return !root.isEnd && root.children.size === 0;
  }
  return false;
}

// Longest common prefix of all words in trie
function longestCommonPrefix(trie) {
  let node = trie.root;
  let prefix = '';
  while (node.children.size === 1 && !node.isEnd) {
    const [ch, child] = node.children.entries().next().value;
    prefix += ch;
    node = child;
  }
  return prefix;
}

const t2 = new Trie();
['flower','flow','flight'].forEach(w => t2.insert(w));
console.log(longestCommonPrefix(t2)); // 'fl'
